using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Shell;

namespace LinkLAN.Desktop;
public sealed class Dialog {
 public Window Window{get;}public StackPanel Body{get;}=new(){Margin=new Thickness(18,12,18,8)};public StackPanel Buttons{get;}=new(){Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(12)};public TextBlock Error{get;}=new(){TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,0)};
 public Dialog(MainShell shell,string title,double width=390,double height=0){Window=new Window{Title=title,Owner=shell.Window,Width=width,MinWidth=Math.Min(width,320),SizeToContent=height==0?SizeToContent.Height:SizeToContent.Manual,Height=height==0?400:height,MaxHeight=Math.Max(350,SystemParameters.WorkArea.Height-40),ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,ShowInTaskbar=false,DataContext=shell.VM,Icon=shell.Window.Icon};WindowChrome.SetWindowChrome(Window,new WindowChrome{CaptionHeight=34,ResizeBorderThickness=new Thickness(0),CornerRadius=new CornerRadius(8),GlassFrameThickness=new Thickness(0)});
  var grid=new Grid();grid.RowDefinitions.Add(new(){Height=new GridLength(34)});grid.RowDefinitions.Add(new(){Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new(){Height=GridLength.Auto});var header=new Grid();header.SetResourceReference(Panel.BackgroundProperty,"Panel");var label=new TextBlock{Text=title,Margin=new Thickness(12,0,38,0),FontWeight=FontWeights.SemiBold,TextTrimming=TextTrimming.CharacterEllipsis};header.Children.Add(label);var close=new Button{Content="×",HorizontalAlignment=HorizontalAlignment.Right,Style=(Style)Application.Current.FindResource("TitleButton")};WindowChrome.SetIsHitTestVisibleInChrome(close,true);close.Click+=(_,_)=>Window.Close();header.Children.Add(close);grid.Children.Add(header);var scroll=new ScrollViewer{Content=Body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);grid.Children.Add(scroll);Grid.SetRow(Buttons,2);grid.Children.Add(Buttons);var border=new Border{CornerRadius=new CornerRadius(8),BorderThickness=new Thickness(1),Child=grid};border.SetResourceReference(Border.BackgroundProperty,"Background");border.SetResourceReference(Border.BorderBrushProperty,"InputBorder");Window.Content=border;Error.SetResourceReference(TextBlock.ForegroundProperty,"Bad");Window.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape){Window.Close();e.Handled=true;}};}
 public Button Button(string label,Action action,bool primary=false){var button=new Button{Content=label,MinWidth=85,Margin=new Thickness(6,0,0,0)};if(primary)button.Style=(Style)Application.Current.FindResource("Primary");button.Click+=(_,_)=>action();Buttons.Children.Add(button);return button;}
 public static void Label(Panel panel,string label){panel.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,10,0,5),TextWrapping=TextWrapping.Wrap});}
 public static TextBox Field(Panel panel,string label,string value=""){Label(panel,label);var field=new TextBox{Text=value,MinWidth=100};panel.Children.Add(field);return field;}
 public static PasswordBox Password(Panel panel,string label){Label(panel,label);var field=new PasswordBox();panel.Children.Add(field);return field;}
 public static void Message(MainShell shell,string title,string text,bool copy=false){var d=new Dialog(shell,title);d.Body.Children.Add(new TextBox{Text=text,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,BorderThickness=new Thickness(0),Background=Brushes.Transparent,MaxHeight=400});if(copy)d.Button(shell.VM.L["Копировать"],()=>shell.Copy(text));d.Button(shell.VM.L["Закрыть"],()=>d.Window.Close(),true);d.Window.ShowDialog();}
 public static bool Confirm(MainShell shell,string title,string text){var d=new Dialog(shell,title);d.Body.Children.Add(new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap});bool yes=false;d.Button(shell.VM.L["Отмена"],()=>d.Window.Close());d.Button(shell.VM.L["Да"],()=>{yes=true;d.Window.Close();},true);d.Window.ShowDialog();return yes;}
}
public static class Dialogs {
 public static Window Settings(MainShell shell,int initial=0){var vm=shell.VM;var d=new Dialog(shell,vm.L["Настройки"],540,420);d.Window.ResizeMode=ResizeMode.CanResize;d.Window.MinHeight=370;d.Window.MinWidth=450;var split=new Grid();split.ColumnDefinitions.Add(new(){Width=new GridLength(155)});split.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});var navigation=new ListBox{BorderThickness=new Thickness(0),Background=Brushes.Transparent,ItemContainerStyle=(Style)Application.Current.FindResource("Nav"),Margin=new Thickness(0,0,10,0)};var page=new StackPanel{Margin=new Thickness(12,0,0,0)};Grid.SetColumn(page,1);split.Children.Add(navigation);split.Children.Add(page);d.Body.Children.Add(split);d.Body.Children.Add(d.Error);d.Button(vm.L["Закрыть"],()=>d.Window.Close(),true);
  string[] labels=["Тема оформления","Язык интерфейса","Дополнительно","Уведомления","Сервер","Админ-панель сервера…"];
  async Task Patch(object patch){try{await shell.Patch(patch);d.Error.Text="";}catch(Exception e){d.Error.Text=e.Message;}}
  void Toggle(string label,bool value,Func<bool,object> patch){var c=new CheckBox{Content=new TextBlock{Text=vm.L[label],TextWrapping=TextWrapping.Wrap},IsChecked=value,Style=(Style)Application.Current.FindResource("Switch")};c.Click+=async(_,_)=>{c.IsEnabled=false;try{await Patch(patch(c.IsChecked==true));}finally{c.IsEnabled=true;}};page.Children.Add(c);}
  void Radio(string label,bool chosen,Action action){var r=new RadioButton{Content=vm.L[label],IsChecked=chosen,GroupName="choices"};r.Click+=(_,_)=>action();page.Children.Add(r);}
  void Render(){page.Children.Clear();d.Error.Text="";var p=vm.Settings;switch(navigation.SelectedIndex){case 0:Dialog.Label(page,vm.L["Тема оформления"]);foreach(var (key,label) in new[]{("light","Светлая"),("dark","Тёмная"),("auto","Как в Windows")})Radio(label,p.Theme==key,async()=>await Patch(new{theme=key}));break;
   case 1:Dialog.Label(page,vm.L["Язык интерфейса"]);Radio("Русский",p.Language=="ru",async()=>await Patch(new{language="ru"}));Radio("English",p.Language=="en",async()=>await Patch(new{language="en"}));break;
   case 2:Toggle("Подключаться автоматически",p.AutoConnect,v=>new{autoConnect=v});Toggle("Запускать с Windows",p.StartAtLogon,v=>new{startAtLogon=v});Toggle("Запускать свёрнутым в трей",p.StartInTray,v=>new{startInTray=v});break;
   case 3:Toggle("Показывать уведомления",p.NotifyDesktop,v=>new{notifyDesktop=v});Toggle("Звук уведомлений",p.NotifySound,v=>new{notifySound=v});Toggle("Учитывать режим «Не беспокоить»",p.RespectFocus,v=>new{respectFocus=v});break;
   case 4:var server=Dialog.Field(page,vm.L["Адрес API-сервера"],p.Server);var name=Dialog.Field(page,vm.L["Имя компьютера"],p.DeviceName);var button=new Button{Content=vm.L["Сохранить"],Margin=new Thickness(0,15,0,0),HorizontalAlignment=HorizontalAlignment.Left,Style=(Style)Application.Current.FindResource("Primary")};button.Click+=async(_,_)=>{button.IsEnabled=false;d.Error.Text=vm.L["Подключение…"];try{await shell.Engine.Call("server",new{server=server.Text.Trim(),deviceName=name.Text.Trim()});await shell.Refresh();d.Error.Text="";}catch(Exception e){d.Error.Text=e.Message;}finally{button.IsEnabled=true;}};page.Children.Add(button);break;
   case 5:Dialog.Label(page,vm.L["Админ-панель сервера…"]);var info=new TextBlock{Text=vm.L["Панель откроется в браузере. Введите токен администратора на странице входа."],TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)};page.Children.Add(info);var open=new Button{Content=vm.L["Открыть"],HorizontalAlignment=HorizontalAlignment.Left};open.Click+=(_,_)=>{if(Uri.TryCreate(p.Server,UriKind.Absolute,out var uri)&&uri.Scheme is "https" or "http")shell.Open(MainShell.AdminAddress(uri));else d.Error.Text=vm.L["Укажите сервер в настройках"];};page.Children.Add(open);break;}}
  void Culture(){int index=navigation.SelectedIndex;navigation.Items.Clear();foreach(var label in labels)navigation.Items.Add(vm.L[label]);navigation.SelectedIndex=Math.Max(0,index);d.Window.Title=vm.L["Настройки"];Render();}
  navigation.SelectionChanged+=(_,_)=>Render();foreach(var label in labels)navigation.Items.Add(vm.L[label]);navigation.SelectedIndex=Math.Clamp(initial,0,5);vm.CultureChanged+=Culture;d.Window.Closed+=(_,_)=>vm.CultureChanged-=Culture;return d.Window;
 }
 public static void Network(MainShell shell,bool create){var vm=shell.VM;var d=new Dialog(shell,vm.L[create?"Создать сеть":"Присоединиться к сети…"]);var name=Dialog.Field(d.Body,vm.L["Имя сети"]);var mode=new CheckBox{Content=vm.L[create?"По приглашению":"Использовать код приглашения"],Style=(Style)Application.Current.FindResource("Switch")};d.Body.Children.Add(mode);var pass=Dialog.Password(d.Body,vm.L["Пароль"]);PasswordBox? confirmation=create?Dialog.Password(d.Body,vm.L["Подтверждение пароля"]):null;TextBox? invite=!create?Dialog.Field(d.Body,vm.L["Код приглашения"]):null;if(invite!=null)invite.IsEnabled=false;mode.Click+=(_,_)=>{pass.IsEnabled=mode.IsChecked!=true;if(confirmation!=null)confirmation.IsEnabled=pass.IsEnabled;if(invite!=null){invite.IsEnabled=mode.IsChecked==true;name.IsEnabled=!invite.IsEnabled;}};d.Body.Children.Add(d.Error);d.Button(vm.L["Отмена"],()=>d.Window.Close());Button? submit=null;submit=d.Button(vm.L[create?"Создать":"Присоединиться"],async()=>{submit!.IsEnabled=false;try{await shell.Engine.Call(create?"create":"join",new{name=name.Text.Trim(),password=pass.Password,confirm=confirmation?.Password??pass.Password,mode=mode.IsChecked==true?"invite":"password",invite=mode.IsChecked==true?invite?.Text.Trim():""});pass.Clear();confirmation?.Clear();await shell.Refresh();d.Window.Close();}catch(Exception e){d.Error.Text=e.Message;}finally{submit.IsEnabled=true;}},true);submit.IsDefault=true;d.Window.ShowDialog();}
 public static void Properties(MainShell shell,NodeVM node){var l=shell.VM.L;var d=new Dialog(shell,l["Свойства"]+": "+node.Name,390);void Row(string label,string value){Dialog.Label(d.Body,l[label]);d.Body.Children.Add(new TextBox{Text=value,IsReadOnly=true,BorderThickness=new Thickness(0),Background=Brushes.Transparent,Padding=new Thickness(0,2,0,2)});}Row("Имя компьютера",node.Name);Row("ID устройства",node.Id);Row("IP-адрес",node.Ip);Row("Имя сети",node.Network.Name);Row("Статус",l[node.Online?"В сети":"Не в сети"]);Row("Тип соединения",string.IsNullOrEmpty(node.Peer?.Route)?"—":node.Peer.Route);Row("Задержка",node.Peer is {Measured:true,Reachable:true,RttMs:long ms}?(ms<1?"<1":ms.ToString())+" ms":"—");Row("Отпечаток ключа",node.Peer?.Fingerprint??"—");d.Button(l["Закрыть"],()=>d.Window.Close(),true);d.Window.ShowDialog();}
}
